do $$ begin
  if exists (select 1 from b2_links where supplier_id is null) then raise exception 'a supplier code in this batch does not exist'; end if;
end $$;

-- One link per supplier and SKU; the balance file's primary supplier is main (cost = its Main Cost), the others
-- are alternatives with no price yet (TBC in the file).
insert into scm.supplier_material_bindings
    (company_id, supplier_id, material_kind, item_code, material_name, supplier_sku, unit_price_sen, price_valid_from, is_main_supplier, notes)
select (select id from public.companies where code = 'HOUZS'), l.supplier_id, 'mfg_product', l.code, l.name, '', l.cost, case when l.priced then date '2026-10-26' end,
       l.main and not exists (select 1 from scm.supplier_material_bindings b where b.company_id = (select id from public.companies where code = 'HOUZS') and b.material_kind = 'mfg_product'
                                                                            and b.item_code = l.code and b.is_main_supplier),
       'sku-batch2 2026-10-26: ' || case when l.main then 'main supplier, cost from the balance file' else 'alternative supplier, price TBC' end
  from b2_links l
 where not exists (select 1 from scm.supplier_material_bindings b where b.company_id = (select id from public.companies where code = 'HOUZS') and b.material_kind = 'mfg_product'
                                                                   and b.item_code = l.code and b.supplier_id = l.supplier_id);

insert into scm.supplier_binding_price_history
    (company_id, supplier_id, material_kind, item_code, unit_price_sen, is_main_supplier, effective_from, notes, created_by, applied_at)
select (select id from public.companies where code = 'HOUZS'), l.supplier_id, 'mfg_product', l.code, l.cost, true, date '2026-10-26', 'sku-batch2 2026-10-26: balance file Main Cost', 'sku-batch2 2026-10-26', now()
  from b2_links l
 where l.priced
   and not exists (select 1 from scm.supplier_binding_price_history h where h.company_id = (select id from public.companies where code = 'HOUZS') and h.supplier_id = l.supplier_id
                     and h.material_kind = 'mfg_product' and h.item_code = l.code and h.effective_from = date '2026-10-26');

